for (Map<String, Object> n : rows(fixture, "notes")) {
    Instant at = n.get("at") == null ? clock.instant() : seedInstant(n.get("at").toString());
    jdbc.update("INSERT INTO note (id, target_type, target_id, text, created_at) VALUES (?, ?, ?, ?, ?)",
